<script setup>

import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'

import { getAdminData } from '../services/adminService.js'

import ProductPhoto from '../components/ProductPhoto.vue'

import { available, stockState, money, productBody, batchBody, saleBody, uploadProductImage, validateProductImage } from '../services/adminInventoryUtils.js'

import { vietnamDay, periodRange, receivedInRange, supplierKey, supplierStatistics } from '../services/adminInventoryStats'
const props = defineProps({ auth: { type: Object, required: true }, initialRange: { type: Object, default: null } })

const emit = defineEmits(['session-expired'])

const products=ref([]), suppliers=ref([]), batches=ref([]), tab=ref('products')

const loading=ref(false), batchLoading=ref(false), saving=ref(false), error=ref(''), success=ref(''), batchError=ref(''), supplierError=ref('')

const productLoaded=ref(false), supplierLoaded=ref(false), batchesLoaded=ref(false)

const query=ref(''), state=ref('active'), page=ref(1), batchPage=ref(1), batchStatus=ref('PENDING'), batchProduct=ref('')

const modal=ref(null), dialog=ref(null), form=ref({}), formError=ref(''), confirmation=ref(null), confirmDialog=ref(null), confirmError=ref('')

const selectedImage=ref(null), imagePreview=ref(''), imageInput=ref(null), uploadingImage=ref(false)
const sale=ref({ productId:'', unit:'TUBES', quantity:1 }), lastSale=ref(null)

const controllers=new Set();let disposed=false,loadVersion=0,batchVersion=0

const statsPreset=ref('month'), statsRange=ref(periodRange('month'))
const supplierDetail=ref(null), supplierDetailDialog=ref(null)
watch(()=>props.initialRange,r=>{if(r){statsPreset.value='custom';statsRange.value={...r}}},{immediate:true,deep:true})
const supplierStats=computed(()=>supplierStatistics(suppliers.value,batches.value,statsRange.value))
const statsTotals=computed(()=>supplierStats.value.reduce((a,s)=>({count:a.count+s.count,tubes:a.tubes+s.tubes,amount:a.amount+s.amount,pendingAmount:a.pendingAmount+s.pendingAmount}),{count:0,tubes:0,amount:0,pendingAmount:0}))
const selectedSupplierStats=computed(()=>supplierStats.value.find(s=>s.id===supplierDetail.value?.id))
const supplierDetailRows=computed(()=>batches.value.filter(b=>supplierKey(b)===supplierDetail.value?.id&&receivedInRange(b,statsRange.value)).sort((a,b)=>(b.receivedAt||'').localeCompare(a.receivedAt||'')||b.id-a.id))
const undatedReceived=computed(()=>batches.value.filter(b=>(b.status||'RECEIVED')==='RECEIVED'&&!b.receivedAt).length)
function setStatsPeriod(value){statsPreset.value=value;statsRange.value=periodRange(value)}
function closeSupplierDetail(){supplierDetail.value=null;supplierDetailDialog.value?.close()}
watch(supplierDetail,async()=>{await nextTick();if(disposed)return;if(supplierDetail.value&&!supplierDetailDialog.value?.open)supplierDetailDialog.value?.showModal();else if(!supplierDetail.value)supplierDetailDialog.value?.close()})
const statuses={OK:'Đủ hàng',LOW:'Sắp hết',OUT:'Hết hàng'}

const selectedProduct=computed(()=>products.value.find(p=>p.id===Number(sale.value.productId)))

const saleTotal=computed(()=>Number(sale.value.quantity||0)*(sale.value.unit==='PIECES'?selectedProduct.value?.piecePrice||0:selectedProduct.value?.tubePrice||0))

const filtered=computed(()=>products.value.filter(p=>`${p.name} ${p.brand} ${p.id}`.toLocaleLowerCase('vi').includes(query.value.toLocaleLowerCase('vi'))).filter(p=>state.value==='all'||(state.value==='active'?p.active:state.value==='inactive'?!p.active:state.value==='attention'?p.active&&stockState(p)!=='OK':p.active&&stockState(p)===state.value)))

const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12)))

const shown=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))

const activeProducts=computed(()=>products.value.filter(p=>p.active))

const lowProducts=computed(()=>activeProducts.value.filter(p=>stockState(p)!=='OK').length)

const filteredBatches=computed(()=>batches.value.filter(b=>(!batchProduct.value||b.product?.id===Number(batchProduct.value))&&(!batchStatus.value||(b.status||'RECEIVED')===batchStatus.value)).sort((a,b)=>b.id-a.id))

const batchPages=computed(()=>Math.max(1,Math.ceil(filteredBatches.value.length/10)))

const shownBatches=computed(()=>filteredBatches.value.slice((batchPage.value-1)*10,batchPage.value*10))

const pendingCount=computed(()=>batches.value.filter(b=>b.status==='PENDING').length)

const stamp=d=>d?new Date(/[Zz]|[+-]\d\d:\d\d$/.test(d)?d:`${d}+07:00`).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'Chưa nhận'

watch([query,state],()=>{page.value=1})

watch(pages,n=>{page.value=Math.min(page.value,n)})

watch([batchStatus,batchProduct],()=>{batchPage.value=1})

watch(batchPages,n=>{batchPage.value=Math.min(batchPage.value,n)})

watch(tab,async value=>{if(['batches','suppliers'].includes(value)&&!batchesLoaded.value&&!loading.value&&!batchLoading.value)await loadBatches()})

watch(modal,async()=>{await nextTick();if(disposed)return;if(modal.value&&!dialog.value?.open)dialog.value?.showModal();else if(!modal.value)dialog.value?.close()})

watch(confirmation,async()=>{await nextTick();if(disposed)return;if(confirmation.value&&!confirmDialog.value?.open)confirmDialog.value?.showModal();else if(!confirmation.value)confirmDialog.value?.close()})

function err(e){if(e.status===401)emit('session-expired');return e.name==='AbortError'?'Yêu cầu hết thời gian. Tải lại dữ liệu để kiểm tra kết quả trước khi thử lại.':e instanceof TypeError?'Không kết nối được máy chủ.':e.message}

async function api(path,options={}){const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),15000);try{return await getAdminData(path,props.auth.accessToken,controller.signal,options)}finally{clearTimeout(timeout);controllers.delete(controller)}}

async function load(){if(saving.value)return;const version=++loadVersion;loading.value=true;error.value='';supplierError.value='';const results=await Promise.allSettled([api('/api/products/admin'),api('/api/suppliers')]);if(disposed||version!==loadVersion)return;for(let i=0;i<results.length;i++){const r=results[i];if(r.status==='fulfilled'&&Array.isArray(r.value)){if(i===0){products.value=r.value;productLoaded.value=true}else{suppliers.value=r.value;supplierLoaded.value=true}}else{const message=r.status==='rejected'?err(r.reason):'Dữ liệu trả về không phải danh sách.';if(i===0){error.value=message;productLoaded.value=false}else{supplierError.value=message;supplierLoaded.value=false}}}loading.value=false;if(['batches','suppliers'].includes(tab.value))await loadBatches();else batchesLoaded.value=false}

async function loadBatches(){if(!productLoaded.value)return;const version=++batchVersion;batchLoading.value=true;batchError.value='';const output=[],failures=[];let cursor=0;const all=[...products.value];await Promise.all(Array.from({length:Math.min(4,all.length)},async()=>{while(cursor<all.length&&!disposed){const p=all[cursor++];try{const data=await api(`/api/inventory-batches/product/${p.id}`);if(!Array.isArray(data))throw Error('Dữ liệu lô hàng không hợp lệ');output.push(...data)}catch(e){failures.push(`${p.name}: ${err(e)}`)}}}));if(disposed||version!==batchVersion)return;batches.value=output;batchesLoaded.value=failures.length===0;batchError.value=failures.join(' · ');batchLoading.value=false}

function close(){if(saving.value)return;clearSelectedImage();modal.value=null;formError.value='';dialog.value?.close()}

function closeConfirm(){if(saving.value)return;confirmation.value=null;confirmError.value='';confirmDialog.value?.close()}

function outside(e,fn){if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)fn()}

function edit(p=null){clearSelectedImage();form.value=p?{...p,detail:p.detail??'',piecePrice:p.piecePrice??''}:{name:'',brand:'',detail:'',imageUrl:'',piecesPerTube:12,tubePrice:'',piecePrice:'',minimumStockTubes:20,targetStockTubes:50};formError.value='';modal.value={kind:'product',product:p}}

function newBatch(p=null){form.value={productId:p?.id||'',supplierId:'',quantityTubes:p?Math.max(1,(p.targetStockTubes||50)-available(p)):1,importPricePerTube:''};formError.value='';modal.value={kind:'batch'}}

function newSupplier(s=null){form.value=s?{...s,name:s.name||'',phone:s.phone||'',address:s.address||''}:{name:'',phone:'',address:''};formError.value='';modal.value={kind:'supplier',supplier:s}}
function askDeleteSupplier(s){confirmation.value={kind:'supplier-delete',supplier:s};confirmError.value=''}

function askActive(p){confirmation.value={kind:'active',product:p,active:!p.active};confirmError.value=''}

function askReceive(b){if(b.status!=='PENDING')return;confirmation.value={kind:'receive',batch:b};confirmError.value=''}

function selectSale(p){sale.value={productId:p.id,unit:'TUBES',quantity:1};tab.value='sales';lastSale.value=null}

function askSale(){try{const p=selectedProduct.value;const body=saleBody(sale.value,p);confirmation.value={kind:'sale',product:p,body,unit:sale.value.unit,total:saleTotal.value,quantity:Number(sale.value.quantity)};confirmError.value='';error.value=''}catch(e){error.value=e.message}}

function clearSelectedImage(){
  if(imagePreview.value)URL.revokeObjectURL(imagePreview.value)
  imagePreview.value='';selectedImage.value=null
  if(imageInput.value)imageInput.value.value=''
}
function chooseImage(event){
  const file=event.target.files?.[0]
  if(!file)return
  try{validateProductImage(file)}catch(e){formError.value=e.message;event.target.value='';return}
  clearSelectedImage();selectedImage.value=file;imagePreview.value=URL.createObjectURL(file);formError.value=''
}
async function uploadSelectedImage(){
  const controller=new AbortController();controllers.add(controller)
  const timeout=setTimeout(()=>controller.abort(),30000)
  uploadingImage.value=true
  try{return await uploadProductImage(selectedImage.value,props.auth.accessToken,controller.signal)}
  finally{clearTimeout(timeout);controllers.delete(controller);uploadingImage.value=false}
}
async function submit(){
  if(saving.value||!modal.value)return
  formError.value='';let body,path,method='POST'
  try{
    if(modal.value.kind==='product'){
      if(selectedImage.value)validateProductImage(selectedImage.value)
      body=productBody({...form.value,imageUrl:selectedImage.value?'/uploads/products/pending':form.value.imageUrl},modal.value.product)
      path=modal.value.product?`/api/products/${modal.value.product.id}`:'/api/products'
      if(modal.value.product)method='PUT'
    }else if(modal.value.kind==='batch'){
      body=batchBody(form.value);path='/api/inventory-batches'
      if(!supplierLoaded.value)throw Error('Tải lại danh sách nhà cung cấp trước khi tạo lô.')
    }else{
      const name=form.value.name.trim();if(!name)throw Error('Nhập tên nhà cung cấp.')
      body={name,phone:form.value.phone.trim(),address:form.value.address.trim()};path=modal.value.supplier?`/api/suppliers/${modal.value.supplier.id}`:'/api/suppliers';if(modal.value.supplier)method='PUT'
    }
  }catch(e){formError.value=e.message;return}
  const kind=modal.value.kind;saving.value=true
  try{
    if(kind==='product'&&selectedImage.value){
      const imageUrl=await uploadSelectedImage()
      if(disposed)return
      form.value.imageUrl=imageUrl;body.imageUrl=imageUrl;clearSelectedImage()
    }
    await api(path,{method,body:JSON.stringify(body)})
    if(disposed)return
    saving.value=false;close()
    success.value=kind==='batch'?'Đã tạo lô chờ nhận. Tồn kho chưa tăng.':kind==='supplier'?'Đã thêm nhà cung cấp.':'Đã lưu sản phẩm.'
    if(kind==='batch')tab.value='batches'
    await load()
  }catch(e){if(!disposed)formError.value=err(e)}finally{saving.value=false}
}

async function execute(){if(saving.value||!confirmation.value)return;const c=confirmation.value;let path,method='POST',body;if(c.kind==='supplier-delete'){path=`/api/suppliers/${c.supplier.id}`;method='DELETE'}else if(c.kind==='active'){path=`/api/products/${c.product.id}/active`;method='PATCH';body={active:c.active}}else if(c.kind==='receive'){path=`/api/inventory-batches/${c.batch.id}/receive`}else{path='/api/inventory-batches/counter-sales'+(c.unit==='PIECES'?'/pieces':'');body=c.body}saving.value=true;confirmError.value='';try{const result=await api(path,{method,...(body?{body:JSON.stringify(body)}:{})});if(disposed)return;if(c.kind==='sale')lastSale.value=result;saving.value=false;closeConfirm();success.value=c.kind==='supplier-delete'?'Đã xóa nhà cung cấp.':c.kind==='sale'?`Đã xuất bán ${c.quantity} ${c.unit==='PIECES'?'quả':'ống'}; kho đã được cập nhật.`:c.kind==='receive'?'Đã xác nhận nhận hàng và cộng kho.':c.active?'Đã mở bán lại sản phẩm.':'Đã xóa khỏi danh mục bán; lịch sử kho vẫn được giữ.';await load()}catch(e){if(!disposed)confirmError.value=err(e)}finally{saving.value=false}}

onMounted(load)

onUnmounted(()=>{clearSelectedImage();disposed=true;loadVersion++;batchVersion++;controllers.forEach(c=>c.abort())})

</script>



<template>

<div class="inventory-workspace">

  <header class="hero"><div><span class="eyebrow">CARROT / KHO & BÁN LẺ</span><h2>Sẵn cầu. Sẵn sàng ra sân.</h2><p>Sản phẩm, nguồn hàng và từng lượt xuất bán — quản lý trong một nơi.</p></div><button class="hero-refresh" :disabled="loading||batchLoading||saving" @click="load">↻ {{loading?'Đang tải…':'Làm mới'}}</button></header>

  <p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="success" class="message success" role="status">✓ {{success}}</p><p v-if="supplierError" class="message error" role="alert">Nhà cung cấp: {{supplierError}}</p>

  <div class="metrics"><button @click="tab='products';state='active'"><span class="metric-icon">▦</span><div><small>Đang kinh doanh</small><strong>{{activeProducts.length}}</strong><span>Sản phẩm trong danh mục</span></div></button><button @click="tab='products';state='attention'"><span class="metric-icon amber">!</span><div><small>Cần bổ sung</small><strong>{{lowProducts}}</strong><span>Sắp hết hoặc hết hàng</span></div></button><button @click="tab='batches';batchStatus='PENDING'"><span class="metric-icon blue">↓</span><div><small>Lô chờ nhận</small><strong>{{batchesLoaded?pendingCount:'—'}}</strong><span>{{batchesLoaded?'Chưa cộng vào tồn kho':'Mở tab nhập hàng để tải'}}</span></div></button><button @click="tab='suppliers'"><span class="metric-icon">♧</span><div><small>Nhà cung cấp</small><strong>{{supplierLoaded?suppliers.length:'—'}}</strong><span>Đối tác nhập cầu</span></div></button></div>

  <nav class="tabs" aria-label="Quản lý kho"><button v-for="t in [{id:'products',name:'Sản phẩm'},{id:'batches',name:'Nhập & nhận hàng'},{id:'sales',name:'Bán lẻ tại quầy'},{id:'suppliers',name:'Nhà cung cấp'}]" :key="t.id" :class="{selected:tab===t.id}" :aria-pressed="tab===t.id" @click="tab=t.id">{{t.name}}</button></nav>

  <section v-if="tab==='products'" class="panel"><div class="section-heading"><div><h3>Danh mục sản phẩm</h3><p>Ảnh sản phẩm, giá bán và tồn kho khả dụng.</p></div><button class="primary" :disabled="saving||loading||!productLoaded" @click="edit()">＋ Thêm sản phẩm</button></div><div class="filters"><label class="search"><span>⌕</span><input v-model="query" placeholder="Tìm tên cầu, thương hiệu hoặc mã…" aria-label="Tìm sản phẩm" /></label><select v-model="state" aria-label="Lọc sản phẩm"><option value="active">Đang bán</option><option value="all">Tất cả sản phẩm</option><option value="attention">Cần bổ sung</option><option value="LOW">Sắp hết</option><option value="OUT">Hết hàng</option><option value="OK">Đủ hàng</option><option value="inactive">Đã ngừng bán</option></select></div>

    <div class="product-grid" :aria-busy="loading"><article v-for="p in shown" :key="p.id" class="product-card" :class="{inactive:!p.active}"><div class="photo-wrap"><ProductPhoto :src="p.imageUrl" :name="p.name" /><span class="badge photo-badge" :class="!p.active?'inactive':stockState(p)">{{!p.active?'Ngừng bán':statuses[stockState(p)]}}</span></div><div class="product-copy"><span class="brand">{{p.brand}} <span>#{{p.id}}</span></span><h4>{{p.name}}</h4><p class="spec">{{p.piecesPerTube}} quả / ống</p><p class="product-description" :title="p.detail||''">{{p.detail?.trim()||'Chưa có mô tả sản phẩm.'}}</p><div class="prices"><div><strong>{{money(p.tubePrice)}}</strong><small>/ ống</small></div><span>{{p.piecePrice?`${money(p.piecePrice)} / quả`:'Chưa bán lẻ theo quả'}}</span></div><div class="stock"><div><small>Khả dụng</small><strong>{{available(p)}} <span>ống</span></strong></div><div><small>Tồn thực tế</small><b>{{p.stockQuantityTubes||0}}</b></div><div><small>Đang giữ</small><b>{{p.reservedQuantityTubes||0}}</b></div></div><div class="product-actions"><button :disabled="saving||loading" @click="edit(p)">Sửa</button><button :disabled="saving||loading||!supplierLoaded" @click="newBatch(p)">Nhập hàng</button><button v-if="p.active" class="primary" :disabled="saving||loading||!productLoaded" @click="selectSale(p)">Bán lẻ ↗</button><button v-else class="primary" :disabled="saving||loading" @click="askActive(p)">Bán lại</button></div><button v-if="p.active" class="delete-link" :disabled="saving||loading" @click="askActive(p)">Xóa khỏi danh mục bán</button></div></article></div><div v-if="!shown.length" class="empty">{{loading?'Đang tải sản phẩm…':!productLoaded?'Chưa tải được danh mục. Hãy làm mới.':'Không có sản phẩm phù hợp.'}}</div><footer class="pagination"><span>{{filtered.length}} sản phẩm</span><button :disabled="page<=1" @click="page--">←</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">→</button></footer>

  </section>

  <section v-if="tab==='batches'" class="panel"><div class="section-heading"><div><h3>Nhập hàng & duyệt nhận</h3><p>Tạo lô → kiểm tra hàng thực nhận → xác nhận cộng kho.</p></div><button class="primary" :disabled="saving||loading||!productLoaded||!supplierLoaded" @click="newBatch()">＋ Tạo lô nhập</button></div><div class="flow-note"><span>01 · Tạo lô chờ nhận</span><i>→</i><span>02 · Kiểm tra đủ số ống</span><i>→</i><strong>03 · Duyệt nhận hàng</strong></div><p v-if="batchError" class="message error" role="alert">Một số lô chưa tải được: {{batchError}} <button :disabled="batchLoading" @click="loadBatches">Thử lại</button></p><div class="filters"><select v-model="batchProduct" aria-label="Lọc lô theo sản phẩm"><option value="">Tất cả sản phẩm</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="batchStatus" aria-label="Lọc trạng thái lô"><option value="PENDING">Chờ nhận hàng</option><option value="RECEIVED">Đã nhận hàng</option><option value="">Tất cả trạng thái</option></select><button :disabled="batchLoading||saving" @click="loadBatches">↻ Tải lô hàng</button></div><div class="table-wrap"><table><thead><tr><th>Sản phẩm / mã lô</th><th>Nhà cung cấp</th><th>Đặt / đã nhận</th><th>Còn lại</th><th>Giá nhập / ống</th><th>Trạng thái</th><th>Xử lý</th></tr></thead><tbody><tr v-for="b in shownBatches" :key="b.id"><td><div class="table-product"><ProductPhoto :src="b.product?.imageUrl" :name="b.product?.name"/><div><strong>{{b.product?.name}}</strong><small>{{b.batchCode}} · #{{b.id}}</small></div></div></td><td><strong>{{b.supplier?.name||'Lô cũ chưa có nhà cung cấp'}}</strong><small>{{b.supplier?.phone}}</small></td><td><strong>{{b.quantityOrderedTubes??b.quantityReceivedTubes}} / {{b.quantityReceivedTubes||0}} ống</strong></td><td>{{b.quantityRemainingTubes||0}} ống<small>{{b.loosePiecesRemaining||0}} quả lẻ</small></td><td>{{money(b.importPricePerTube)}}<small>Tổng lô {{money((b.quantityOrderedTubes??b.quantityReceivedTubes)*b.importPricePerTube)}}</small></td><td><span class="badge" :class="b.status==='PENDING'?'LOW':'OK'">{{b.status==='PENDING'?'Chờ nhận':'Đã nhận'}}</span><small>{{stamp(b.receivedAt)}}</small></td><td><button v-if="b.status==='PENDING'" class="primary" :disabled="saving||batchLoading||loading" @click="askReceive(b)">✓ Duyệt nhận hàng</button><span v-else class="received">✓ Đã cộng kho</span></td></tr><tr v-if="!shownBatches.length"><td colspan="7" class="empty">{{batchLoading?'Đang tải lô hàng…':!productLoaded?'Cần tải danh mục sản phẩm trước.':'Không có lô hàng phù hợp.'}}</td></tr></tbody></table></div><footer class="pagination"><span>{{filteredBatches.length}} lô{{batchError?' · dữ liệu chưa đầy đủ':''}}</span><button :disabled="batchPage<=1" @click="batchPage--">←</button><span>{{batchPage}} / {{batchPages}}</span><button :disabled="batchPage>=batchPages" @click="batchPage++">→</button></footer></section>

  <section v-if="tab==='sales'" class="panel"><div class="section-heading"><div><h3>Bán lẻ tại quầy</h3><p>Bán nguyên ống hoặc từng quả. Kho xuất theo lô cũ trước.</p></div><span class="badge OK">Xuất hàng ngay khi xác nhận</span></div><div class="sale-layout"><form class="sale-form" @submit.prevent="askSale"><label>Sản phẩm<select v-model="sale.productId" required :disabled="saving||loading||!productLoaded"><option value="" disabled>Chọn sản phẩm đang bán</option><option v-for="p in activeProducts" :key="p.id" :value="p.id">{{p.name}} · {{available(p)}} ống khả dụng</option></select></label><fieldset :disabled="saving"><legend>Đơn vị bán</legend><label :class="{chosen:sale.unit==='TUBES'}"><input v-model="sale.unit" type="radio" value="TUBES" name="sale-unit"/>Nguyên ống</label><label :class="{chosen:sale.unit==='PIECES'}"><input v-model="sale.unit" type="radio" value="PIECES" name="sale-unit"/>Quả lẻ</label></fieldset><label>Số lượng {{sale.unit==='PIECES'?'quả':'ống'}}<input v-model="sale.quantity" required type="number" min="1" step="1" :disabled="saving"/></label><p class="hint">{{sale.unit==='PIECES'?'Backend dùng quả lẻ còn lại, rồi mở thêm ống khả dụng khi cần.':'Các ống đang giữ cho booking không được dùng để bán.'}}</p><div class="sale-total"><span>TỔNG TIỀN HÀNG</span><strong>{{money(saleTotal)}}</strong></div><button class="primary wide" :disabled="saving||loading||!productLoaded||!selectedProduct||!selectedProduct.active||(sale.unit==='PIECES'&&!selectedProduct.piecePrice)">Kiểm tra & xác nhận bán →</button><p v-if="sale.unit==='PIECES'&&selectedProduct&&!selectedProduct.piecePrice" class="hint warning">Sản phẩm chưa có giá bán/quả. Sửa sản phẩm để bổ sung.</p></form><aside class="sale-preview"><template v-if="selectedProduct"><ProductPhoto :src="selectedProduct.imageUrl" :name="selectedProduct.name"/><span class="brand">{{selectedProduct.brand}}</span><h3>{{selectedProduct.name}}</h3><p>{{selectedProduct.piecesPerTube}} quả / ống</p><div class="preview-prices"><span>Giá / ống<strong>{{money(selectedProduct.tubePrice)}}</strong></span><span>Giá / quả<strong>{{money(selectedProduct.piecePrice)}}</strong></span></div><div class="stock"><div><small>Ống khả dụng</small><strong>{{available(selectedProduct)}}</strong></div><div><small>Đang giữ</small><b>{{selectedProduct.reservedQuantityTubes||0}}</b></div></div></template><div v-else class="empty">Chọn sản phẩm để xem ảnh và giá bán.</div></aside></div><div v-if="lastSale" class="sale-receipt" role="status"><div><span class="badge OK">✓ Đã xuất bán</span><h4>{{lastSale.issueCode}}</h4><p>{{lastSale.product?.name}} · {{lastSale.quantityPieces||lastSale.quantityTubes}} {{lastSale.quantityPieces?'quả':'ống'}}</p><small>{{stamp(lastSale.issuedAt)}}</small></div><strong>{{money(lastSale.totalAmount)}}</strong></div><p class="footnote">Đây là phiếu xuất bán. Backend hiện chưa có API duyệt riêng hoặc ghi nhận phương thức thu tiền cho đơn bán lẻ.</p></section>

  <section v-if="tab==='suppliers'" class="panel"><div class="section-heading"><div><h3>Nhà cung cấp & giá trị nhập hàng</h3><p>Thống kê theo ngày nhận hàng, sử dụng giá nhập riêng của từng lô.</p></div><button class="primary" :disabled="saving||loading||!supplierLoaded" @click="newSupplier()">＋ Thêm nhà cung cấp</button></div>
  <div class="supplier-period"><div class="period-presets"><button v-for="t in [{id:'today',label:'Hôm nay'},{id:'week',label:'Tuần này'},{id:'month',label:'Tháng này'}]" :key="t.id" :class="{selected:statsPreset===t.id}" @click="setStatsPeriod(t.id)">{{t.label}}</button></div><label>Từ ngày<input v-model="statsRange.from" type="date" @change="statsPreset='custom'"/></label><label>Đến ngày<input v-model="statsRange.to" type="date" :min="statsRange.from" @change="statsPreset='custom'"/></label><button :disabled="loading||batchLoading||saving" @click="load">↻ Cập nhật</button></div>
  <p v-if="!statsRange.from||!statsRange.to||statsRange.from>statsRange.to" class="message error">Chọn khoảng ngày hợp lệ.</p><p v-if="batchError" class="message error" role="alert">Chưa tải đủ lô hàng, chưa thể tổng kết: {{batchError}} <button :disabled="batchLoading" @click="loadBatches">Thử lại</button></p>
  <div class="supplier-metrics"><article><small>GIÁ TRỊ ĐÃ NHẬP / KỲ CHỌN</small><strong>{{batchesLoaded?money(statsTotals.amount):'—'}}</strong><p>Theo giá nhập, không phải giá bán</p></article><article><small>LÔ ĐÃ NHẬN / KỲ CHỌN</small><strong>{{batchesLoaded?statsTotals.count:'—'}}</strong><p>{{batchesLoaded?statsTotals.tubes:'—'}} ống đã nhập vào kho</p></article><article class="pending-metric"><small>HÀNG CHỜ NHẬN / TẤT CẢ NGÀY</small><strong>{{batchesLoaded?money(statsTotals.pendingAmount):'—'}}</strong><p>Chưa cộng vào giá trị đã nhập</p></article></div>
  <p class="footnote">Tuần này bắt đầu từ thứ Hai. Ngày tính theo giờ Việt Nam. Giá trị đã nhập = số ống đã nhận × giá nhập/ống, không giảm khi bán hàng.</p><p v-if="undatedReceived" class="hint warning">{{undatedReceived}} lô đã nhận chưa có ngày nhận, không tính vào thống kê theo kỳ.</p>
  <div class="table-wrap"><table><thead><tr><th>Nhà cung cấp</th><th>Liên hệ</th><th>Lô đã nhận</th><th>Ống đã nhập</th><th>Giá trị đã nhập</th><th>Hàng chờ / mọi ngày</th><th>Thao tác</th></tr></thead><tbody><tr v-for="s in supplierStats" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.id==='unassigned'?'Dữ liệu lô cũ':`#${s.id}`}}</small></td><td>{{s.phone||'—'}}<small class="supplier-address">{{s.address||'—'}}</small></td><td>{{batchesLoaded?s.count:'—'}}</td><td>{{batchesLoaded?s.tubes:'—'}}</td><td><strong class="supplier-amount">{{batchesLoaded?money(s.amount):'—'}}</strong></td><td>{{batchesLoaded?money(s.pendingAmount):'—'}}<small>{{batchesLoaded?s.pendingCount:'—'}} lô chờ nhận</small></td><td><div class="supplier-actions"><button :disabled="!batchesLoaded||batchLoading" @click="supplierDetail=s">Chi tiết ↗</button><template v-if="s.id!=='unassigned'"><button :disabled="saving||loading" @click="newSupplier(s)">Sửa</button><button class="supplier-delete" :disabled="saving||loading" @click="askDeleteSupplier(s)">Xóa</button><button :disabled="saving||!productLoaded" @click="newBatch();form.supplierId=s.id">Nhập hàng</button></template></div></td></tr><tr v-if="!supplierStats.length"><td colspan="7" class="empty">{{loading||batchLoading?'Đang tải dữ liệu…':!supplierLoaded?'Chưa tải được nhà cung cấp.':'Chưa có nhà cung cấp.'}}</td></tr></tbody></table></div><p v-if="batchLoading" class="hint" role="status">Đang tải các lô hàng để thống kê…</p></section>
  <dialog ref="supplierDetailDialog" class="modal supplier-detail-modal" aria-labelledby="supplier-stats-title" @cancel.prevent="closeSupplierDetail" @click="outside($event,closeSupplierDetail)"><template v-if="supplierDetail"><header class="modal-heading"><div><span class="eyebrow">CHI TIẾT HÀNG ĐÃ NHẬP</span><h3 id="supplier-stats-title">{{supplierDetail.name}}</h3></div><button class="icon-button" aria-label="Đóng chi tiết nhà cung cấp" @click="closeSupplierDetail">✕</button></header><div class="modal-body"><p class="hint">{{statsRange.from.split('-').reverse().join('/')}} – {{statsRange.to.split('-').reverse().join('/')}}</p><div class="supplier-detail-total"><span>{{selectedSupplierStats?.count||0}} lô · {{selectedSupplierStats?.tubes||0}} ống đã nhận</span><strong>{{money(selectedSupplierStats?.amount||0)}}</strong></div><div class="table-wrap"><table><thead><tr><th>Sản phẩm / lô</th><th>Ngày nhận</th><th>Số ống đã nhận</th><th>Giá nhập/ống</th><th>Thành tiền nhập</th></tr></thead><tbody><tr v-for="b in supplierDetailRows" :key="b.id"><td><strong>{{b.product?.name}}</strong><small>{{b.batchCode}}</small></td><td>{{stamp(b.receivedAt)}}</td><td>{{b.quantityReceivedTubes||0}}</td><td>{{money(b.importPricePerTube)}}</td><td><strong>{{money((b.quantityReceivedTubes||0)*(b.importPricePerTube||0))}}</strong></td></tr><tr v-if="!supplierDetailRows.length"><td colspan="5" class="empty">Không có lô đã nhận trong khoảng ngày này.</td></tr></tbody></table></div></div><footer class="modal-footer"><button @click="closeSupplierDetail">Đóng</button></footer></template></dialog>

  <dialog ref="dialog" class="modal edit-modal" aria-labelledby="inventory-edit-title" @cancel.prevent="close" @click="outside($event,close)"><form v-if="modal" @submit.prevent="submit"><header class="modal-heading"><div><span class="eyebrow">QUẢN LÝ KHO</span><h3 id="inventory-edit-title">{{modal.kind==='product'?(modal.product?'Sửa sản phẩm':'Thêm sản phẩm'):modal.kind==='batch'?'Tạo lô nhập hàng':modal.supplier?'Sửa nhà cung cấp':'Thêm nhà cung cấp'}}</h3></div><button type="button" class="icon-button" :disabled="saving" aria-label="Đóng form" @click="close">✕</button></header><div class="modal-body"><template v-if="modal.kind==='product'"><div class="image-editor"><div class="upload-preview"><img v-if="imagePreview" :src="imagePreview" :alt="form.name||'Ảnh đã chọn'"/><ProductPhoto v-else :src="form.imageUrl" :name="form.name"/></div><div><label>Ảnh sản phẩm</label><input ref="imageInput" class="file-input" type="file" accept="image/jpeg,image/png,image/webp" :disabled="saving" @change="chooseImage" aria-label="Chọn ảnh sản phẩm từ máy"/><button type="button" class="primary" :disabled="saving" @click="imageInput?.click()">{{selectedImage?'Đổi ảnh đã chọn':form.imageUrl?'Thay ảnh sản phẩm':'＋ Chọn ảnh từ máy'}}</button><p v-if="selectedImage" class="file-name">{{selectedImage.name}}</p><button v-if="selectedImage" type="button" class="delete-link" :disabled="saving" @click="clearSelectedImage">Bỏ ảnh đã chọn</button><p class="hint">JPG, PNG hoặc WEBP, tối đa 5 MB. Ảnh được tải lên khi bấm Lưu thông tin.</p></div></div><label class="description-field">Mô tả sản phẩm<textarea v-model="form.detail" rows="4" placeholder="Đặc điểm cầu, chất liệu, độ bền, đối tượng phù hợp…" :disabled="saving"></textarea></label><div class="form-grid"><label>Tên sản phẩm<input v-model="form.name" required maxlength="255" :disabled="saving"/></label><label>Thương hiệu<input v-model="form.brand" required maxlength="255" :disabled="saving"/></label><label>Số quả / ống<input v-model="form.piecesPerTube" type="number" min="1" step="1" required :disabled="saving||!!modal.product"/><small v-if="modal.product">Quy cách đã tạo được giữ cố định.</small></label><label>Giá bán / ống (VND)<input v-model="form.tubePrice" type="number" min="1" step="1" required :disabled="saving"/></label><label>Giá bán / quả (VND)<input v-model="form.piecePrice" type="number" min="1" step="1" placeholder="Để trống nếu không bán lẻ quả" :disabled="saving"/></label><label>Ngưỡng nhập thêm (ống)<input v-model="form.minimumStockTubes" type="number" min="0" step="1" required :disabled="saving"/></label><label>Tồn kho mục tiêu (ống)<input v-model="form.targetStockTubes" type="number" :min="Number(form.minimumStockTubes)+1" step="1" required :disabled="saving"/></label></div><p class="hint">Tồn kho tăng khi duyệt nhận lô hàng; sản phẩm mới bắt đầu với 0 ống.</p></template><template v-else-if="modal.kind==='batch'"><p class="callout">Tạo lô chưa cộng kho. Chỉ duyệt nhận sau khi kiểm tra đủ hàng thực tế.</p><div class="form-grid"><label>Sản phẩm<select v-model="form.productId" required :disabled="saving"><option value="" disabled>Chọn sản phẩm</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}{{!p.active?' (ngừng bán)':''}}</option></select></label><label>Nhà cung cấp<select v-model="form.supplierId" required :disabled="saving"><option value="" disabled>Chọn nhà cung cấp</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Số lượng nhập (ống)<input v-model="form.quantityTubes" type="number" min="1" step="1" required :disabled="saving"/></label><label>Giá nhập / ống (VND)<input v-model="form.importPricePerTube" type="number" min="1" step="1" required :disabled="saving"/></label></div><p v-if="!suppliers.length" class="hint warning">Chưa có nhà cung cấp. Đóng form và thêm tại tab Nhà cung cấp.</p><div class="sale-total"><span>GIÁ TRỊ LÔ DỰ KIẾN</span><strong>{{money(Number(form.quantityTubes||0)*Number(form.importPricePerTube||0))}}</strong></div></template><template v-else><label>Tên nhà cung cấp<input v-model="form.name" required maxlength="255" :disabled="saving"/></label><div class="form-grid"><label>Số điện thoại<input v-model="form.phone" type="tel" maxlength="30" :disabled="saving"/></label><label>Địa chỉ<input v-model="form.address" maxlength="255" :disabled="saving"/></label></div></template><p v-if="formError" class="message error" role="alert">{{formError}}</p></div><footer class="modal-footer"><button type="button" :disabled="saving" @click="close">Quay lại</button><button class="primary" :disabled="saving">{{uploadingImage?'Đang tải ảnh…':saving?'Đang lưu…':modal.kind==='batch'?'Tạo lô chờ nhận':'Lưu thông tin'}}</button></footer></form></dialog>

  <dialog ref="confirmDialog" class="modal confirm-modal" aria-labelledby="inventory-confirm-title" @cancel.prevent="closeConfirm" @click="outside($event,closeConfirm)"><form v-if="confirmation" @submit.prevent="execute"><header class="modal-heading"><span class="eyebrow">XÁC NHẬN THAO TÁC</span><button type="button" class="icon-button" :disabled="saving" aria-label="Đóng xác nhận" @click="closeConfirm">✕</button></header><div class="modal-body"><div class="confirm-symbol" :class="{danger:confirmation.kind==='active'&&!confirmation.active}">{{confirmation.kind==='receive'?'↓':confirmation.kind==='sale'?'↗':confirmation.active?'✓':'×'}}</div><h3 id="inventory-confirm-title">{{confirmation.kind==='supplier-delete'?'Xóa nhà cung cấp':confirmation.kind==='receive'?'Duyệt nhận hàng vào kho':confirmation.kind==='sale'?'Xác nhận bán & giao hàng':confirmation.active?'Mở bán lại sản phẩm':'Xóa khỏi danh mục bán'}}</h3><div v-if="confirmation.kind!=='supplier-delete'" class="confirm-product"><ProductPhoto :src="(confirmation.product||confirmation.batch?.product)?.imageUrl" :name="(confirmation.product||confirmation.batch?.product)?.name"/><div><strong>{{(confirmation.product||confirmation.batch?.product)?.name}}</strong><small>{{(confirmation.product||confirmation.batch?.product)?.brand}}</small></div></div><template v-if="confirmation.kind==='supplier-delete'"><div class="supplier-delete-summary"><strong>{{confirmation.supplier.name}}</strong><small>{{confirmation.supplier.phone||'Chưa có số điện thoại'}}</small><small>{{confirmation.supplier.address||'Chưa có địa chỉ'}}</small></div><p class="callout">Chỉ xóa được nhà cung cấp chưa có lô nhập. Nếu đã có dữ liệu liên quan, backend sẽ giữ lại lịch sử và báo lỗi.</p></template><template v-else-if="confirmation.kind==='receive'"><div class="confirmation-lines"><p>Mã lô<strong>{{confirmation.batch.batchCode}}</strong></p><p>Nhà cung cấp<strong>{{confirmation.batch.supplier?.name||'—'}}</strong></p><p>Số lượng cộng kho<strong>{{confirmation.batch.quantityOrderedTubes}} ống</strong></p><p>Giá trị lô<strong>{{money(confirmation.batch.quantityOrderedTubes*confirmation.batch.importPricePerTube)}}</strong></p></div><p class="callout">Xác nhận đã nhận đủ {{confirmation.batch.quantityOrderedTubes}} ống. Backend hiện nhận toàn bộ lô, không nhận từng phần.</p></template><template v-else-if="confirmation.kind==='sale'"><div class="confirmation-lines"><p>Số lượng giao<strong>{{confirmation.quantity}} {{confirmation.unit==='PIECES'?'quả':'ống'}}</strong></p><p>Tổng tiền hàng<strong>{{money(confirmation.total)}}</strong></p></div><p class="callout">Xác nhận sẽ tạo phiếu xuất và trừ kho ngay. Kiểm tra số lượng trước khi giao khách.</p></template><p v-else class="hint">{{confirmation.active?'Sản phẩm sẽ xuất hiện lại trong danh mục đang bán.':'Sản phẩm ngừng bán, không nhận đơn mới. Tồn kho, lô nhập và lịch sử booking được giữ lại; có thể mở bán lại.'}}</p><p v-if="confirmError" class="message error" role="alert">{{confirmError}}</p></div><footer class="modal-footer"><button type="button" :disabled="saving" @click="closeConfirm">Quay lại</button><button :class="confirmation.kind==='active'&&!confirmation.active?'danger-button':'primary'" :disabled="saving">{{saving?'Đang xử lý…':confirmation.kind==='supplier-delete'?'Xác nhận xóa':confirmation.kind==='receive'?'✓ Đã nhận đủ hàng':confirmation.kind==='sale'?'✓ Xác nhận xuất bán':confirmation.active?'Mở bán lại':'Xóa khỏi danh mục'}}</button></footer></form></dialog>

</div>

